<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Desktop Environment</title>
    <style>
        * { box-sizing: border-box; }
        body { margin: 0; padding: 0; overflow: hidden; font-family: Arial, sans-serif; background: #1c1b22; }
        #desktop { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: #313245; }

        .window { 
            position: absolute; width: 400px; height: 300px; background: #282a36; color: white;
            display: flex; flex-direction: column; border-radius: 5px; box-shadow: 0 4px 12px rgba(0,0,0,.7);
        }

        .title-bar { 
            background: #6272a4; color: white; padding: 5px 10px; display: flex; justify-content: space-between; align-items: center;
            cursor: move; border-radius: 5px 5px 0 0; user-select: none;
        }

        .win-close { background: #ff5555; color: white; border: none; padding: 3px 6px; margin-left: auto; cursor: pointer; float: right; }

        #taskbar { position: fixed; bottom: 0; left: 0; right: 0; height: 40px; background: #1c1b22; border-top: 1px solid #333; display: flex; justify-content: center; align-items: center; gap: 15px; }
        .launcher { padding: 8px 16px; background: #444; color: white; border-radius: 3px; cursor: pointer; font-size: 14px; }

        /* Files window styles */
        #files-window #path-bar { display: flex; align-items: center; padding: 5px 10px; background: #282a36; border-bottom: 1px solid #444; }
        #files-path { font-size: 12px; margin-right: 10px; color: #6272a4; cursor: default; }
        #files-up { background: none; border: none; color: #ff79c6; cursor: pointer; padding: 3px 8px; font-size: 14px; }

        .fs-container { flex: 1; overflow-y: auto; padding: 10px; display: flex; flex-wrap: wrap; gap: 5px; background: #282a36; }
        .fs-item { padding: 8px; background: #444; border-radius: 3px; cursor: pointer; font-size: 12px; color: #f8f8f2; white-space: nowrap; }

        /* Notepad window styles */
        .notepad-container { flex-direction: column; height: 100%; padding: 5px 10px; display: flex; flex: 1; overflow: hidden; }
        #tabs { background: #282a36; border-bottom: 1px solid #444; padding: 5px; display: flex; gap: 5px; flex-wrap: wrap; }
        .tab { padding: 5px 10px; cursor: pointer; background: #444; border-radius: 3px; font-size: 12px; color: white; white-space: nowrap; }
        .tab.active { background: #6272a4; }

        #editor { flex: 1; resize: none; background: #191a21; color: #f8f8f2; font-family: monospace; padding: 10px; border-radius: 3px; border: none; width: 100%; }
    </style>
</head>
<body>
    <div id="desktop"></div>

    <!-- Taskbar -->
    <div id="taskbar">
        <button class="launcher" id="open-files">Files</button>
        <button class="launcher" id="open-notepad">Notepad</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" style="display: none;">
        <div class="title-bar">
            <span>Files</span>
            <button class="win-close" onclick="document.getElementById('files-window').style.display='none';">&times;</button>
        </div>
        <div id="path-bar">
            <button id="files-up">↑</button>
            <span id="files-path"></span>
        </div>
        <div class="fs-container" id="file-list"></div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" style="display: none;">
        <div class="title-bar">
            <span>Notepad</span>
            <button class="win-close" onclick="document.getElementById('notepad-window').style.display='none';">&times;</button>
        </div>
        <div class="notepad-container">
            <div id="tabs"></div>
            <textarea id="editor" spellcheck="false"></textarea>
        </div>
    </div>

    <!-- Filesystem data -->
    <script>
        // File System Structure (static fake filesystem)
        const fs = {
            '/': {
                bin: {}, etc: {}, home: { user: {} }, usr: {}, var: {}
            }
        };

        fs['/home'] = {}; 
        fs['/home/user'] = { Documents: {}, Downloads: {}, Pictures: {} };

        // Helper to get path segments and navigate filesystem
        function getCurrentDir(path) {
            return (path === '/') ? fs['/'] : (fs[path] || {});
        }

        // Files App Logic
        let currentPath = '/';
        const fileContainer = document.getElementById('file-list');
        const pathDisplay = document.getElementById('files-path');

        function renderFiles() {
            const dirContents = getCurrentDir(currentPath);
            fileContainer.innerHTML = '';
            pathDisplay.textContent = currentPath;

            Object.keys(dirContents).forEach(name => {
                const itemDiv = document.createElement('div');
                itemDiv.className = 'fs-item';
                itemDiv.textContent = name;

                if (dirContents[name] === Object(dirContents[name])) {
                    // It's a directory
                    itemDiv.style.cursor = 'pointer';
                    itemDiv.addEventListener('dblclick', () => {
                        currentPath += '/' + name;
                        renderFiles();
                    });
                } else {
                    // File (no navigation)
                }

                fileContainer.appendChild(itemDiv);
            });

            const upBtn = document.getElementById('files-up');
            const parentPath = currentPath.split('/').slice(0, -1).join('/') || '/';
            upBtn.onclick = () => { 
                if (currentPath !== '/') {
                    currentPath = parentPath;
                    renderFiles();
                }
            };
        }

        // Initialize files window on load
        document.getElementById('open-files').onclick = () => {
            currentPath = '/';
            renderFiles();
            document.getElementById('files-window').style.display = 'block';
        };

        // Notepad App Logic with localStorage persistence
        let tabs = JSON.parse(localStorage.getItem('notepadTabs')) || [];

        function generateTabId() { return Date.now().toString(36) + Math.random().toString(36).substr(2, 5); }

        const tabsContainer = document.getElementById('tabs');
        const editor = document.getElementById('editor');

        // Render tabs UI from saved data
        function renderTabs() {
            tabsContainer.innerHTML = '';
            tabs.forEach((tab, index) => {
                const tabEl = document.createElement('div');
                tabEl.className = `tab${index === activeTabIndex ? ' active' : ''}`;
                tabEl.textContent = tab.id; // Could be better naming if needed
                tabEl.dataset.index = index;

                tabEl.onclick = () => {
                    activeTabIndex = index;
                    editor.value = tab.content || '';
                    renderTabs(); // Update active class styling
                };

                tabsContainer.appendChild(tabEl);
            });

            if (!tabs.length) return;
            const newTabBtn = document.createElement('div');
            newTabBtn.textContent = '+';
            newTabBtn.id = 'new-tab';
            newTabBtn.style.cursor = 'pointer';
            newTabBtn.onclick = createNewTab;

            tabsContainer.appendChild(newTabBtn);

            // Ensure last tab is active if not set
            if (activeTabIndex === -1 && tabs.length > 0) {
                activeTabIndex = tabs.length-1;
                editor.value = tabs[activeTabIndex].content || '';
            }
        }

        let activeTabIndex = -1; // Track index of currently selected tab

        function createNewTab() {
            const newId = generateTabId();
            tabs.push({id: newId, content: ''});
            localStorage.setItem('notepadTabs', JSON.stringify(tabs));
            activeTabIndex = tabs.length - 1;
            editor.value = '';

            renderTabs();
        }

        document.getElementById('new-tab')?.addEventListener('click', createNewTab);

        // Editor event: save to localStorage on edit
        editor.addEventListener('input', () => {
            if (activeTabIndex !== -1) {
                tabs[activeTabIndex].content = editor.value;
                localStorage.setItem('notepadTabs', JSON.stringify(tabs));
            }
        });

        // Open notepad window handler
        document.getElementById('open-notepad').onclick = () => {
            if (tabs.length === 0) createNewTab(); // Ensure at least one tab exists

            renderTabs();
            document.getElementById('notepad-window').style.display = 'block';
        };

        // Initial render check for localStorage data when opening notepad
    </script>
</body>
</html>
